package guidancecontent

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"strings"
	"testing"

	"github.com/jaxxstorm/fed/internal/catalog"
	"github.com/jaxxstorm/fed/internal/readiness"
)

// These are independently authored source-comparison findings, not approvals
// derived from the recipe text. Export is explicit; ordinary tests never rewrite
// a review hash after an implementation change.
type certificationComparisonNote struct{ obligation, proof, timing, uncertainty string }

var certificationComparisonNotes = map[string]certificationComparisonNote{
	"FRC-CSO-FCP": {"The profile-selection and practice-application duties are separate; the resource security-category note permits justified variation, including third-party resources, rather than excluding those resources. Added separate assertions for profile identity and actual practice application.", "A saved target profile establishes the decision; practice-to-resource implementation records establish application. Neither alone proves both duties.", "No periodic interval or profile-selection deadline is stated.", "Appropriate resource security categories depend on the actual information handled or impacted; the rule does not prescribe one category for every resource."},
	"FRC-CSO-PKG": {"The package must actually be supplied to FedRAMP for initial certification and contain all three listed components: CPO overview, per-relevant-requirement implementation/validation/assessment information, and a real or example OCR. The rule-linked schema concerns the package overview.", "Manifest, component revisions and transmission provenance address different facts. The three item assertions preserve the real-or-example OCR alternative; a supplied shell package is insufficient.", "Initial certification is the event; the separate freshness rule supplies the seven-day lookback.", "An example OCR demonstrates the permitted package component, not an operational reporting history. Linked schemas are identified, but this comparison has not validated an actual service payload against those schemas."},
	"FRC-CSO-JSN": {"Schema-valid JSON applies when the rule contains a schema, with explicit rule exceptions. Public-data web compatibility is mandatory; the included CORS/header details use lowercase should and must not be inflated into independent uppercase MUST rules.", "Payload-to-corresponding-schema results and browser-origin endpoint observations prove distinct properties. Content-Type application/json and X-Content-Type-Options nosniff remain explicit; a CLI fetch or browser with security bypasses is insufficient.", "At information supply; no new refresh frequency appears in the rule or narrative.", "The rule does not specify a universal CORS origin configuration or require private JSON to be public. Actual linked-schema validation remains service-specific."},
	"FRC-CSO-MRA": {"Responsibility and accountability stay with the provider for accuracy and completeness of every package contribution, particularly third-party material. Added an assertion separating substantive content review from naming an accountable owner.", "Contributor provenance plus provider factual checks and missing-content reconciliation can support this duty; a contract transferring responsibility or an owner signature alone cannot.", "Ongoing responsibility has no separately mandated numeric review cadence.", "The source does not mandate a particular sign-off form or tool; the proposed review records are an inferred evidence method."},
	"FRC-CSO-POP": {"The prohibition is seeking both Rev5 Program and 20x Program for the same offering. The note expressly permits Rev5 Agency plus 20x Program while strongly discouraging it; the draft preserves that distinction.", "Application and listing histories must distinguish type from path and refer to the same offering. Merely showing one current profile is weaker than accounting for simultaneous pursuits.", "Applies whenever those Program certifications are sought; no waiting period is invented.", "Determining whether two offerings are the same requires factual boundary evidence; this prohibition does not itself resolve product-boundary disputes."},
	"FRC-CLA-ASF": {"The three frameworks are alternatives: historical-impact-level Rev5 including Ready, SOC 2 Type II, or GovRAMP. A completed certification/equivalent process includes independent assessment if applicable. Corrected per-item assertions so unselected alternatives are not failed obligations.", "The elected framework, completed report/process and service coverage must be established together. Type I, an engagement letter or an unlisted framework cannot substitute for completed Type II.", "Completion must fall within the past 12 months; collection or download dates cannot reset completion age.", "The source permits Rev5 beyond Ready, whereas EAM enumerates Ready materials specifically. Materials for a non-Ready historical Rev5 route need clarification rather than automatic substitution of a RAR."},
	"FRC-CLA-EAM": {"Only the elected framework's material set is required, with all necessary-party supply. SOC 2 includes the complete report, conditional bridge/gap and supplemental evidence, verified engagement and upcoming-report estimate; Ready/GovRAMP require RAR, SAP and their other required material. Corrected list assertions that could imply all alternatives.", "A framework-specific manifest and recipient delivery/access reconciliation establish different duties. Neither the report cover nor the certification alone proves complete material supply.", "Supply accompanies Class A assessment materials; no separate numeric delivery interval is stated.", "ASF accepts historical Rev5 including non-Ready routes, but EAM only names Ready for the FedRAMP material list. The precise non-Ready material set is unresolved by this excerpt."},
	"FRC-CLA-MFR": {"All FRC-CLA rules and 23 enumerated additional entries require address/mapping in the package. Inclusion does not erase each listed rule's force or conditions. The note requires KSI information even for intended future Rev5 pursuit and discourages bare see-SOC-2 references.", "Each enumerated entry has its own mapping assertion; package inclusion and substantive source-linked decisions are distinct. A blanket framework certificate cannot show coverage of 23 entries.", "At Class A package supply; individual included duties retain their separate clocks.", "Addressing a MAY or SHOULD rule in the FRC-CLA subset must preserve its optional/recommended activity and definition-level documentation duties, rather than force every activity."},
	"FRC-CLA-RFR": {"The 11 listed rules are recommended if applicable, including separate Rev5/20x maintenance rules and initial/ongoing incident reports. SHOULD requires documented decisions and weighed implications; the correction makes that explicit without converting execution to MUST.", "An applicability/disposition crosswalk with entry-specific evidence demonstrates considered handling. Marking the whole list compliant without resolving its type-specific entries does not.", "No common deadline is supplied by the list; each addressed rule retains its own timing.", "Whether a listed item applies still depends on type and factual scope; the recommendation cannot override an excluded Rev5-only item."},
	"FRC-CLA-OFR": {"The nine optional rules remain MAY if applicable; there is no automatic election of independent assessment, quarterly meetings or vulnerability-reporting options.", "Documented elections and corresponding entry-level evidence distinguish adoption from non-election. Correctly recording non-election is not evidence of performing an elected duty.", "This optional list adds no clock; any adopted duty's own timing remains relevant.", "MAY's recommended documentation is distinct from mandatory implementation. A service must determine its own elections."},
	"FRC-CLA-IVV": {"A recognized assessor's independent verification AND validation of the Class A package before submission is permission, not a requirement to hire an assessor.", "Election, recognized identity, exact package revision and completed verification/validation conclusions are distinct from an engagement contract.", "If elected, completion precedes submission; there is no numeric lead time here.", "Non-election is permitted. This optional package review must not erase the separate underlying-framework assessment duty."},
	"FRC-APP-MLF": {"The listing must predate applying, and the four Marketplace references remain individually identified. A request for listing is not listing.", "Dated listing history and application receipt prove order; separate MLR/PML/AGU/DCP mappings address the referenced requirements.", "Before application, with no additional waiting period.", "The referred Marketplace rules contain their own details. This plan is a listing-first crosswalk, not proof that those distinct obligations have been met."},
	"FRC-APP-AFC": {"The provider completes the application form in full to request initial assessment; notification metadata supplies the exact help.fedramp.gov form destination.", "Complete transmitted fields, provider submission identity and receipt distinguish a filed application from a draft or form URL.", "The event is requesting initial assessment; the source states no numeric submission deadline.", "A receipt supports submission but cannot by itself establish substantive truth of every application field."},
	"FRC-APP-FCP": {"Current service status and both provider verification and validation within seven days are distinct facts. The clause assertions correctly separate currentness from freshness and do not mistake recent file edits for fresh tests.", "Supply timestamp, original run dates and package-to-current-service change reconciliation are needed together. A recent verification alone cannot establish recent validation.", "Previous 7 days relative to initial package supply; not seven business days and not a general recurring weekly schedule.", "The source does not describe a dispensation for changes after the tests; intervening changes require explicit factual reconciliation rather than presumed freshness."},
	"FRC-APP-FIA": {"Class A MAY supply the fresh recognized-service assessment; B/C/D MUST. Recognition, actual completed assessment and scope are retained independently of freshness.", "Completed results, original completion date, recognized-service provenance and supply date support the obligation. Contract execution or a newly downloaded old report does not.", "Previous 3 months, not 90 days. The stale-update route is separately constrained by FRC-APP-USA.", "The general IVV rule can permit explicitly prioritized direct FedRAMP assessment, while this initial-freshness text names a recognized independent service. This comparison does not infer a new exception here."},
	"FRC-APP-NTP": {"Third parties, expressly including assessment services, must not apply on the provider's behalf. The note permits preparation assistance; authorship and actual submission must not be conflated.", "Submission audit identity and provider-versus-third-party relationship establish who applied. A provider-branded form or provider authorization given to an outside submitter is not equivalent to direct provider application.", "At application, with no numerical lookback.", "The rule does not enumerate every employment/affiliate arrangement; uncertain submitter relationships need factual review."},
	"FRC-APP-USA": {"The optional freshening route substitutes a recognized service's review of changes from original assessment to current state for full reassessment, unless the stale assessment exceeds nine months.", "Original baseline/date, complete change inventory and independent change-review conclusions establish coverage and eligibility. A provider-only delta memo or last-release-only review does not.", "More than 9 months is outside the permission; age is not reset by a refresh or report download.", "The source supplies no separate numeric expiration for the change review itself. It cannot be used to invent indefinite serial extensions."},
	"FRC-APS-ATO": {"This is a Rev5 Agency provider rule requiring completed sponsor ATO, signed letter and agency transmission through official government channels; it is not a 20x ATO prerequisite.", "The excluded plan correctly imposes no evidence checklist on these 20x profiles. In the stated Rev5 context a signed letter alone would still not prove direct official agency transmission.", "Completion is required when seeking that Rev5 Agency certification; no extra interval is stated.", "Exclusion is relative to the inventoried 20x profile, not a declaration that the sponsor's ATO duty is universally absent."},
	"FRC-CCL-UCC": {"New certification application and advance satisfaction of all target requirements are distinct. Despite broad prose examples, the pinned subset metadata restricts Changing Certification Class to Rev5 Agency B/C/D; current 20x variants must retain their exclusions.", "No provider action checklist is created for excluded variants. In the stated scope, a new application alone cannot establish prior target-class satisfaction.", "Applicable requirements must be met in advance; the preferred incremental path creates no numeric lead time.", "The broad upgrade examples include A while subset metadata lists Rev5 Agency B/C/D. This source tension is not resolved by broadening catalog applicability."},
	"FRC-CCL-DCC": {"Downgrade requires a new certification application in the pinned Rev5 Agency subset; its DNP reference does not silently upgrade SHOULD advance notice to MUST.", "Excluded 20x variants appropriately have no downgrade checklist. An edited class label would not prove a new application in the applicable context.", "At downgrade application; the linked 120-day notice is a separate recommendation.", "Broad downgrade prose and narrow Rev5 Agency subset metadata diverge. Preserve the resolver exclusion pending authoritative clarification, rather than applying this as a 20x rule."},
	"FRC-CCL-DNP": {"The notice recommendation covers intended downgrade OR cancellation and all necessary parties. It is not a mandatory waiting period; SHOULD still requires a documented, reasoned disposition.", "For applicable scope, intended effective date, recipient roster and per-party delivery dates establish notice coverage and lead time. An internal decision alone cannot.", "At least 120 days in advance is the recommended interval; do not reinterpret it as business days.", "The pinned subset is Rev5 Agency despite broadly worded cancellation guidance. These 20x exclusions do not settle policy for every cancellation scenario."},
	"FRC-CSX-VVK": {"Class A permits automation without a numeric count; B recommends at least one method per KSI; C requires two and D four. Persistent accuracy AND completeness verification/validation must not collapse into run success or repeated copies of one method.", "Per-KSI distinct method register, underlying source comparisons, denominators and dated results show different facts. The explicit clause assertions retain method coverage and repeated substantive evaluations.", "Persistently allows intentional irregularity/interruptions with known status; no daily cadence is stated.", "The source does not prescribe a taxonomy for distinct automated methods; counting differences requires explained technical judgment, not merely counting jobs."},
	"FRC-CSX-VVR": {"Class A MAY and B/C/D SHOULD automate SDR accuracy and completeness for rules when applicable. The provider-context note leaves implementation choice to the provider; no per-rule method minimum exists. Added separate completeness/accuracy and persistent-result assertions.", "Rule-to-SDR denominator, source-of-truth comparisons and execution outcomes distinguish content correctness from syntactic JSON validation. Skips and inapplicable automation remain visible.", "Persistent activity retains known status and intentional interruptions, with no specified fixed frequency.", "Which rules can reasonably be automated is provider-dependent; this rule does not authorize declaring every rule inapplicable to avoid a reasoned SHOULD disposition."},
	"FRC-CSX-MAS": {"ALL KSIs across ALL aspects within MAS is a recommendation, not a license to reduce scope to infrastructure scanners. The draft preserves uppercase SHOULD and the need for a reasoned documented handling decision.", "MAS inventory and KSI-to-aspect coverage with evidence and gaps establish coverage; a handful of account scan exports does not establish all aspects.", "No independent periodic interval is supplied.", "Actual MAS membership depends on the offering and shared responsibilities; this source comparison cannot determine its factual boundary."},
	"FRC-CSF-BSL": {"The Rev5 class-specific baseline is a minimum SDR control/enhancement list, not a generic control count. The full rule object and page retain B/C/D list identities while all inventoried 20x plans remain excluded.", "No baseline-implementation assertions are imposed on 20x. A future applicable Rev5 assessment would require identity-level comparison, not simply equal totals.", "Seeking the selected Rev5 certification is the stated context; no cycle is supplied here.", "Exclusion from this 20x inventory does not validate a service's separate Rev5 baseline or additional control selection."},
	"FRC-CSF-ACP": {"All organization-defined parameters must be assigned following Rev5 guidance and documented in the SDR. Those two duties remain context only for the excluded 20x plans.", "In applicable scope, parameter-to-control assignments and SDR inclusion would be distinct proof duties; unfilled baseline brackets are insufficient.", "No numeric period accompanies the assignment/documentation requirement.", "The actual guidance-constrained parameter values are not established by this excluded playbook."},
	"FRC-CSF-FFG": {"Following Rev5 Controls Guidance applies to both implementation and documentation of all applicable controls. The draft does not impose that Rev5-only checklist on 20x.", "A promise to follow guidance cannot establish implemented measures or accurate documentation; the excluded variant correctly has no provider evidence tasks.", "No separate numeric deadline is supplied by this rule.", "This comparison does not evaluate individual Rev5 control guidance or service implementations."},
	"FRC-CSF-RDY": {"Legacy Ready conversion uses the later of annual assessment expiration and November 17, 2026, while complete legacy removal is December 31, 2027. The note suggests Class A as a simple route, not an automatic conversion.", "The 20x inventory excludes this Rev5 Ready rule; no new conversion checklist is imposed. Actual legacy status and expiration would be needed to calculate the later-of event.", "The two dates have different functions; December 31, 2027 is not an automatic extension of every conversion deadline.", "A service pursuing 20x might separately possess legacy Ready status. The excluded saved-profile result is not evidence that no legacy conversion obligation exists."},
	"IEC-FRP-ORV": {"FedRAMP periodically reviews provider implementation based on missing reporting or other information; corrective actions and the three-month procedures grace period belong to FedRAMP. Provider-only variants are excluded.", "Provider self-review cannot substitute for FedRAMP review. Lack of reports is a review trigger, not proof of no incidents or failed procedures.", "Periodic review has no numeric cycle; the corrective-action grace period is 3 months and does not suspend report deadlines.", "The actual corrective-action request, grace decision and remediation status require FedRAMP records, which this comparison does not possess."},
	"IEC-CSO-EFR": {"Reportability includes actual OR likely confidentiality/integrity effects on federal customer data. It is not limited to confirmed exfiltration, and availability impact alone is not the quoted trigger. Separate prompt evaluation, scope reasoning and downstream reporting assertions are retained.", "Incident facts, detection/evaluation times, reasoned determination and lifecycle links serve distinct proof duties. The source expressly permits real, simulated or mixed examples; a simulation is not proof of actual live compliance.", "Promptly means without unnecessary delay; no numeric evaluation grace period is created.", "Likelihood is contextual reasonable probability, not a prescribed numeric confidence score; incomplete data does not itself establish non-reportability."},
	"IEC-CSO-DPR": {"A reportable incident defaults to PAIN-5 unless a prompt EFI-conforming estimate exists. The default period and subsequent estimated period must remain distinct; lack of facts cannot be treated as PAIN-1.", "Rating/default history and the dated supporting estimate must reconcile to actual reporting choices. A default configuration with no applied history cannot demonstrate operation.", "The workflow starts the report clock using the default or estimated rating; promptly supplies no fixed estimation allowance.", "The sources do not fully specify clock recalculation on later PAIN changes. Preserve actual chronology and unresolved interpretation rather than retroactively excusing overdue reports."},
	"IEC-CSO-EFI": {"SHOULD estimate cumulative likely agency impact. N1 minimal at one-or-more agencies; N2 narrow at one-or-more; N3 disruptive at one; N4 debilitating at one OR disruptive at multiple; N5 debilitating at multiple. Corrected the missing unknown-effect-as-debilitating treatment and supplied the actual effect definitions.", "Effect category, affected-agency count, contextual likelihood and dated rationale are separate from the assigned label. Each of the five alternatives is evaluated conditionally, not as five ratings that must simultaneously hold.", "Estimate promptly without unnecessary delay; incomplete estimation leaves the reportable-incident default under DPR. No numerical estimation window exists.", "Unknown effect is treated as debilitating until proven otherwise; unknown agency count still requires explicit uncertainty. Do not assume a single agency to lower PAIN. The source's broad note says all incidents, but DPR's operative scope is reportable incidents."},
	"IEC-CSO-IIR": {"Class A SHOULD and B/C/D MUST responsibly notify all affected parties after identification. All eight information fields retain available-information/current-status qualifiers. Notification routes are FedRAMP security email, agency-specific procedures and necessary-party trust-center/USDA Connect update; these are not interchangeable recipients.", "Field-by-field contemporaneous knowledge and per-recipient transmission prove distinct facts. Unknown root cause cannot justify withholding the initial report. Simulation can satisfy example-artifact expectations without proving live deadline performance.", "The selected class/rating table below is IIR only. Workflow clock starts with estimated/default PAIN selection after reportability determination; reporting cannot be delayed by unnecessary estimation delay.", "Business-day calendar, timezone and rating changes need explicit service-level interpretation; no restart/reset rule or weekend calendar is invented. Linked incident-report schema bytes have not been independently validated here."},
	"IEC-CSO-OIR": {"Class A SHOULD and B/C/D MUST report ongoing activity as new information becomes available, including changes OR lack of changes to every prior field and five additional fields. Conditional CVE and unavailable root cause retain current-status treatment.", "Ordered revisions, knowledge timeline and recipient transmissions show prior-field continuity and delivery. An overwritten dashboard or only initial/final reports cannot establish ongoing reporting; simulated series remain labeled.", "Use the OIR class/rating intervals below through the response period, retaining report and PAIN-change timestamps; these are not IIR deadlines.", "The narrative workflow says ongoing until resolution while FIR requires recovery complete too. Preserve the resolution/recovery interval explicitly; this comparison does not invent an unquoted reporting suspension or PAIN-change reset rule."},
	"IEC-CSO-FIR": {"All classes, including A, MUST responsibly notify all affected parties once both incident resolution and recovery completion occur, including final updates to all prior information. Class A's weaker IIR/OIR force does not weaken FIR.", "Separate resolution and recovery-completion evidence, final-to-prior-field comparison and all-recipient delivery establish separate duties. Ticket closure alone is insufficient; a simulated final report proves only the simulated process.", "Use the FIR table below after both completion conditions, not the initial-report clock; retain the later qualifying event.", "The precise operational definition of completed recovery and the business calendar must be justified from incident facts. The rule does not authorize replacing recovery evidence with an administrative closure label."},
	"IEC-CSO-AIR": {"Automation SHOULD minimize human intervention in report generation/delivery to all affected parties. The narrative's hand-crafted-email warning supports evaluating the whole workflow rather than treating ordinary mail transport as sufficient automation.", "Versioned workflow, actual execution, manual handoffs and recipient/failure history show automation extent. A product license or internal alert does not show external reporting automation.", "No separate automation deadline or frequency; the reporting duties keep their own clocks.", "No numeric human-intervention threshold or vendor is mandated; explain residual human steps and the SHOULD disposition."},
	"IVV-CSO-FIA": {"Class A MAY; B/C/D MUST complete independent verification AND validation across all applicable rules with a recognized service OR explicitly prioritized FedRAMP. The direct-FedRAMP note prevents assuming freely available assessment by the program.", "Recognized identity/prioritization, complete rule crosswalk, both kinds of results and actual completion history prove different facts. Engagement letters and provider self-assessment are insufficient.", "Persistently and at least once per year when applicable/elected; interruptions do not erase the explicit annual minimum.", "The rule does not define annual accounting as a fixed 365-day algorithm. Class A's mandatory underlying-framework expectations remain separate from this optional FedRAMP assessment."},
	"IVV-CSO-SEI": {"Supply verification evidence to all necessary assessors showing documented measures actually implemented. The firewall example illustrates configuration deployment, not effectiveness. Separate delivery and deployed-state assertions are retained.", "Documented-to-runtime comparisons and assessor access/delivery show different facts. An undeployed branch or private repository unavailable to assessors cannot establish both.", "At evidence supply, preserve actual deployed revision and observation dates; no test cadence is created.", "All necessary assessors always includes FedRAMP and contracted recognized assessors; additional participants depend on the actual assessment. Inherited implementation claims still need scoped objective evidence."},
	"IVV-CSO-SEE": {"Supply validation evidence to all necessary assessors showing implemented measures achieve intended outcomes. The traffic-blocking example requires actual blocking observations, not merely firewall deployment.", "Outcome intent, actual executed observation/test, results including failures and delivery/access records are distinct proof duties. Verification evidence alone cannot establish validation.", "No new numeric validation cycle is stated here; actual observation dates and assessed versions must remain visible.", "The source specifies no universal success metric; method and evidence sufficiency depend on the implemented measure and claimed outcome."},
	"IVV-CSO-ICP": {"Independent assessment results belong in the package without inappropriate modification. The note permits presentation/format changes while preserving underlying intent; it does not permit suppressing adverse findings.", "Original results, package inclusion map and semantic differences establish inclusion and integrity separately. A renamed positive-only summary is insufficient.", "At package supply or transformation; no new numeric deadline.", "Whether an edit changes underlying intent may need assessor clarification; the source supplies no universal text-diff threshold."},
	"IVV-CSO-DUS": {"Document AND explain representative samples only when samples are used. The prerequisite is conditionally bound to actual sampling, and unknown sampling remains unknown rather than a false no-sampling conclusion.", "Population denominator, selected sample identities and representativeness explanation prove different facts. No sampling means this conditional duty is not triggered; full-population records are a recommended way to establish that fact.", "When samples are used during verification/validation; no mandatory sample count or periodic interval.", "No confidence level or sample-size formula is specified. Representativeness depends on actual population variation and exclusions."},
	"IVV-CSO-STE": {"SHOULD supply all necessary assessors technical explanations, demonstrations and supporting information as necessary for effective verification and validation. Added separate recipient-access and technical-sufficiency assertions.", "Assessor questions, technical content/demonstrations and unresolved information needs support assessment usability; attendance or marketing slides alone cannot.", "As necessary to enable the assessment; no universal response deadline.", "What information is necessary depends on the capabilities and assessors' needs; there is no required demonstration format or mandatory meeting schedule."},
	"IVV-CSO-USR": {"Representative sampling is MAY as appropriate; the note recognizes automation may cover most measures without samples. It does not require sampling or a claim that every automated service tests every resource.", "Population and election records distinguish actual representative sampling from convenient examples. Used samples link to DUS; non-election is not noncompliance.", "During verification/validation, without prescribed sample cadence or count.", "The excerpt supplies no statistical confidence threshold. Full-population coverage is an alternative evidence route, not a new universal requirement."},
	"IVV-CSO-RAA": {"The provider MAY ask for and accept advice during assessment unless likely to compromise objectivity and integrity. Added a distinct exception-boundary assertion rather than relying only on optional election.", "Actual advice exchanges, role boundaries and assessment-specific conflict reasoning are needed; a generic independence clause does not settle the likely-compromise exception.", "During assessment; no numerical interval.", "Likelihood of compromise requires contextual judgment and cannot be inferred solely from any advice having been provided."},
	"IVV-IAS-VIM": {"Assessor verification compares actual implemented measures with documented measures. The note requires technical review such as underlying code as appropriate, explicitly rejecting documentation/screenshots alone.", "The provider-only inventory excludes this assessor duty rather than assigning it to the provider. Provider evidence supply and assessor technical verification are separate responsibilities.", "During independent verification; no standalone numeric cycle here.", "Exclusion does not mean assessor verification is unnecessary in an actual independent assessment; it prevents actor substitution."},
	"IVV-IAS-VEF": {"Assessor validation tests actual technical measures for intended outcomes. It is distinct from implementation verification and cannot be reduced to document or screenshot review.", "Provider-only excluded plans impose no assessor checklist. Actual outcome measurements/work papers would be necessary in the assessor's applicable plan.", "During independent validation; the rule states no separate cycle.", "This source comparison has not evaluated an assessor's test sufficiency or actual outcome results."},
	"IVV-IAS-SUM": {"The assessor supplies a high-level process/findings summary for EACH FedRAMP Practice for provider SDR inclusion. The note says separate SAP/SAR are not required for 20x or Rev5 certifications.", "The provider inventory correctly excludes the assessor duty. An overall positive letter cannot replace per-Practice summaries; recipient supply and SDR destination remain distinct.", "At assessment-results supply; no numeric deadline.", "The no-separate-SAP/SAR note does not cancel Class A EAM's explicit material requirements for an underlying Ready/GovRAMP framework."},
	"IVV-IAS-OSA": {"The assessor supplies an overall verification/validation summary including failures and disputes for CPO inclusion. No FedRAMP template is required; per-Practice SDR summaries remain distinct.", "Excluded provider variants do not fabricate assessor actions. In assessor scope, underlying result-to-summary reconciliation and delivery would distinguish substantive completeness from a positive-only letter.", "At results supply for package overview inclusion; no additional numeric period.", "No standardized template means presentation can vary; it does not permit omitting negative or disputed outcomes."},
	"IVV-IAS-VIP": {"The assessor verifies that assessment-supplied information reaches the package without inappropriate modification. This is independent checking, distinct from the provider's ICP inclusion duty.", "Excluded provider variants retain actor separation. Original-to-final semantic comparison would be needed from the assessor; provider assurance alone would not establish it.", "When verifying package inclusion, without stated numeric lead time.", "Formatting changes can be legitimate under ICP; unresolved underlying-intent changes require clarification rather than automatic byte-equality requirements."},
	"IVV-IAS-EPX": {"Both engaging provider experts and independent research are SHOULD duties for expert qualitative assessment. Provider statements inform judgment but do not substitute for independently testing them.", "The provider-only variant imposes no assessor checklist. In applicable assessor scope, discussion provenance and independent corroboration/conflict records would prove different duties.", "As part of expert qualitative assessment; no numeric schedule.", "The source does not prescribe a research method or count of interviews; the SHOULD definition still requires documented decision handling."},
	"IVV-IAS-SHA": {"Assessor advice is optional subject to the likely-compromise exception. It is the assessor-side duty, not interchangeable with provider RAA permission.", "Excluded provider variants preserve actor scope; actual advice and independence evaluation would be needed to assess the assessor permission boundary.", "During assessment, without a numeric deadline.", "The source defines likelihood contextually; no blanket conclusion that all advice either compromises or never compromises independence is warranted."},
	"IVV-CSX-AIA": {"Class A MUST meet underlying alternative-framework expectations within persistent independent assessment. B/C/D MUST include ALL KSIs in a FedRAMP independent assessment annually. The draft correctly does not substitute optional FIA for the Class A duty.", "A maps framework expectations to completed assessments; B/C/D reconcile every KSI to completed independent results. A certificate alone or a rotating partial KSI set is insufficient for the corresponding branch.", "A follows the underlying framework with persistent activity; B/C/D explicitly at least once per year. No universal annual Class A FedRAMP assessment is invented.", "Class A framework-specific cycles must be established from that framework and actual assessment facts; this rule does not specify one common cycle."},
	"IVV-CSF-AIA": {"Rev5 B/C/D each has a specified annual control/enhancement list. Full source objects retain the class-specific identities; the 20x variants correctly exclude this rule rather than substituting KSI coverage for Rev5 controls.", "No control assessment checklist is imposed on excluded profiles. In Rev5 scope, exact membership and executed annual results would be required rather than only a count or rotating plan.", "At least once per year for listed controls; it is separate from the all-control three-year ceiling.", "These exclusions do not evaluate a separate Rev5 certification or prove annual control assessment completeness."},
	"IVV-CSF-MCA": {"All applicable Rev5 controls must appear in independent assessments every three years, but need not be in the same assessment. The preferred full-control assessment recommendation remains separate.", "Excluded 20x plans add no control tasks. Applicable proof would require dated identity-level coverage across the full window; an annual report title alone cannot establish every-control coverage.", "Every 3 years, not all controls annually under this particular rule.", "The source allows rotations but does not prescribe their schedule; upcoming plans are not completed assessments."},
	"IVV-CSF-ACF": {"Every Rev5 control with a negative finding in the previous independent assessment must be included in the next one. Remediation closure is not a substitute for that inclusion.", "The 20x inventory excludes this Rev5 duty. In scope, prior findings mapped to next-assessment executed results would be distinct from remediation tickets.", "The next independent assessment is the event, not a newly invented grace period.", "This source does not settle a service's actual prior findings or next-assessment coverage."},
	"IVV-CSF-PCA": {"All applicable Rev5 controls in EACH independent assessment is the preferred SHOULD approach, distinct from the three-year mandatory coverage rule. The provider's 20x variant remains excluded.", "No Rev5 checklist is imposed here. Where applicable, per-assessment complete membership comparison and a documented SHOULD disposition are needed; three-year coverage does not prove this recommendation was followed each time.", "Each assessment, with no new annual schedule supplied by this rule alone.", "Reasons for choosing a rotation rather than the preferred full scope require understood implications and documented decisions, not silent disregard."},
}

func TestExportCertificationComparisons(t *testing.T) {
	if os.Getenv("EXPORT_CERTIFICATION_COMPARISONS") != "1" {
		t.Skip("explicit source-comparison export only")
	}
	rules, markdown := os.DirFS("../../testdata/fedramp"), os.DirFS("../../2026-markdown")
	raw, _ := fs.ReadFile(rules, "rules.json")
	schema, _ := fs.ReadFile(rules, "schema.json")
	snapshot, err := catalog.Parse(raw, schema, catalog.PinnedCommit)
	if err != nil {
		t.Fatal(err)
	}
	inv, err := catalog.Inventory(snapshot)
	if err != nil {
		t.Fatal(err)
	}
	variants := map[string]catalog.GuidanceVariant{}
	for _, v := range inv.Variants {
		variants[v.ID] = v
	}
	for domain, build := range map[string]func(fs.FS, fs.FS) (readiness.Package, error){"FRC": FRC, "IEC": IEC, "IVV": IVV} {
		p, err := build(rules, markdown)
		if err != nil {
			t.Fatal(err)
		}
		bundle := ComparisonBundle{RecordingState: "pending_authenticated_service_record", Comparisons: map[string]ComparisonInput{}}
		for _, b := range p.Playbooks {
			n, ok := certificationComparisonNotes[b.RequirementID]
			if !ok {
				t.Fatal("missing independent comparison", b.RequirementID)
			}
			v := variants[b.VariantIDs[0]]
			ref := strings.ToLower(b.RequirementID)
			refs := []string{ref, ref + "-page"}
			context := strings.ToLower(domain) + "-context"
			def := func(titles ...string) []string {
				out := []string{}
				for _, title := range titles {
					out = append(out, strings.ToLower(domain)+"-definition-"+title)
				}
				return out
			}
			finding := func(text string, ids []string) readiness.ReviewFinding {
				return readiness.ReviewFinding{Finding: text, Citations: ids}
			}
			app := fmt.Sprintf("Exact variant %s: %s, force %s, reason %q", v.ID, v.Applicability, v.Force, v.Reason)
			if v.IncludedBy != "" {
				app += "; inclusion source " + v.IncludedBy
			}
			app += ". Compared rule/class statement, audience/type/path subset metadata and transition context. The inventory is provider 20x: initial and optional adoption begin July 4, 2026; ongoing begins January 1, 2027 with grace ending on the first independent assessment started after that date. Unknown next-assessment facts are not assumed true or false."
			app += " Selected source statement for this exact variant: " + v.Statement
			prereq := "The shared service-scoped evidence-context capability is an inferred record-location prerequisite, not a new official technology requirement. Its inputs support the following specific proof comparison: " + n.proof + " Reusing those records does not merge the separate assertion conclusions or establish another service's coverage."
			evidence := n.proof + " Native exports and attributable retained records are alternative carriers of the same underlying facts; neither route permits unsupported attestations. The assertion-specific scope, dates and provenance must still be reconciled."
			timing := n.timing
			if value, ok := v.Details["pain_timeframes"]; ok {
				timing += " Independently compared all five rows with the Markdown table: " + certificationPAINText(value) + " Business days are not elapsed 24-hour days; 0.25 hours is 15 minutes."
			}
			if b.Kind != "actionable" {
				app += " This " + b.Kind + " plan has no assertions, operating steps or prerequisites; the retained statement is context, not an executable provider obligation."
				prereq = "No implementation prerequisite is imposed for this " + b.Kind + " variant. " + n.proof
				evidence = "No operational evidence is demanded by this " + b.Kind + " variant. The comparison preserves the source's distinct proof duties for a later applicable plan: " + n.proof
				timing += " This variant schedules no operational deadline; excluded/unresolved status does not establish timely performance."
			}
			if b.Kind == "needs_decision" {
				app += " The owner must resolve the saved path/class/transition facts; a source comparison cannot make that service decision."
				app += " The corrected decision question is: " + b.DecisionQuestion
			}
			c := readiness.SourceComparison{
				Applicability: finding(app, append(append([]string{}, refs...), context)),
				Obligations:   finding(n.obligation+" The selected official statement is retained verbatim. MUST and MUST NOT are absolute requirement/prohibition in applicable scope; SHOULD allows reasoned departures but requires explanation in security documentation, and MAY is optional with recommended documentation. The corrected guidance preserves those definition-level duties.", append(append([]string{}, refs...), def("must", "must-not", "should", "may")...)),
				Prerequisites: finding(prereq, refs),
				Evidence:      finding(evidence+" Verification confirms fulfilled practices with objective evidence; validation addresses suitability and expected outcomes. Neither a successful export nor this source comparison is either fact.", append(append([]string{}, refs...), def("verification", "validation")...)),
				Timing:        finding(timing+" Where actually invoked, persistently permits intentional, understood and documented irregular cycles/interruptions with known status; promptly means without unnecessary delay. Neither definition adds a universal numeric cadence.", append([]string{ref, ref + "-page", context}, def("persistently", "promptly")...)),
				Limitations:   []string{"This is an agent interpretation of pinned official sources, not an official FedRAMP determination, and may be incomplete or incorrect.", "No service evidence or authenticated content review was recorded. Service-scoped review recording and the complete-catalog publication gate remain outstanding."},
				Uncertainties: []readiness.ReviewFinding{
					finding(n.uncertainty, refs),
					finding("Compared the bound stakeholder definitions: necessary parties always includes FedRAMP and using agency customers, with additional contractual parties possible and prospective customers generally recommended; necessary assessors always includes FedRAMP and contracted recognized assessors; affected parties covers directly or likely affected federal entities and always FedRAMP/directly impacted agencies. These populations are not interchangeable. Actual rosters remain service-specific; definitions do not create a recipient duty where this selected rule has none.", def("all-necessary-parties", "all-necessary-assessors", "all-affected-parties")),
					finding("Compared responsibly and likely: disclosure uses good judgment and avoids broadcasting adversary-helpful details, without excusing required recipient reporting; likely is contextual reasonable probability, not certainty or a fixed percentage. These are interpretive context only where the selected rule invokes them; actual judgments require facts.", def("responsibly", "likely")),
					finding("Compared all five bound impact/effect definitions. Potential agency impact is cumulative across agency customers. Minimal means noticeable to some users; narrow includes some-user interruption under 12 hours OR extremely limited federal-data compromise; disruptive includes many-user interruption under 24 hours OR large/many-type compromise; debilitating includes most-user interruption OR most federal-data compromise, with unknown effect treated as debilitating until proven otherwise. These effect-duration boundaries classify impact, not report deadlines. They do not impose PAIN reporting on unrelated certification or assessment rules. Actual effect and agency count remain factual uncertainties.", def("potential-agency-impact", "minimal-customer-effect", "narrow-customer-effect", "disruptive-customer-effect", "debilitating-customer-effect")),
				},
			}
			if strings.Contains(v.Reason, "conflicts") {
				c.Uncertainties = append(c.Uncertainties, finding("The class-specific statement and subset class metadata conflict in the pinned sources. The draft retains needs_decision rather than silently privileging either field. An authoritative clarification is required before this variant can become an operational checklist; a class-specific table alone does not resolve the conflict.", []string{ref, ref + "-page", context}))
			}
			if err = readiness.ValidateComparison(p, b.ID, c); err != nil {
				t.Fatal(b.ID, err)
			}
			hash, err := readiness.ReviewHash(p, b.ID)
			if err != nil {
				t.Fatal(err)
			}
			bundle.Comparisons[b.ID] = ComparisonInput{ContentHash: hash, Comparison: c}
		}
		data, err := json.MarshalIndent(bundle, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		if err = os.WriteFile("../../guidance/reviews/"+domain+".json", append(data, '\n'), 0644); err != nil {
			t.Fatal(err)
		}
		t.Logf("exported %s: %d independently source-compared exact variants", domain, len(bundle.Comparisons))
	}
}
